// Get the message text from the Telegram trigger
const messageInputText = $input.first().json.request.message

const messageText = messageInputText.toLowerCase().trim();
const ingredientsGreeting = $input.first().json.ingredientsGreeting
const productsGreeting = $input.first().json.productsGreeting
const recipesGreeting = $input.first().json.recipesGreeting


let selectedMode = '';
var responseMessage;

switch (messageText) {
  case 'product':
  case 'products':
    selectedMode = 'PRODUCT';
    responseMessage = productsGreeting;
    break;

  case 'ingredient':
  case 'ingredients':
    selectedMode = 'INGREDIENT';
    responseMessage = ingredientsGreeting;
    break;

  case 'recipe':
  case 'recipes':
    selectedMode = 'RECIPE';
    responseMessage = recipesGreeting;
    break;

  case 'exit':
  case 'main':
  case 'quit':
    selectedMode = 'MAIN';
    responseMessage = 'Returning to *Main Mode*. Standard POS commands active.';
    break;

  default:
    // If it's not a mode-switch command, we keep the current state
    // This allows the message to pass through to the Regex Router
    return [{
      json: {
        isModeSwitch: false,
        text: messageText
      }
    }];
}

// Return the new state data
return [{
  json: {
    isModeSwitch: true,
    newMode: selectedMode,
    response: responseMessage,
    userId: $input.first().json.request[0].user_id
  }
}];

/**
 * Sanitizes AI output to ensure valid JSON is parsed
 * even if the model included Markdown or preamble text.
 */

// Get the raw output from the previous node
let rawOutput = $input.first().json.text;

try {
  // 1. Locate the first '{' and last '}' to strip markdown backticks or extra text
  const start = rawOutput.indexOf('{');
  const end = rawOutput.lastIndexOf('}') + 1;

  if (start === -1 || end === 0) {
    throw new Error("No JSON object found in AI output");
  }

  const cleanJsonString = rawOutput.substring(start, end);

  // 2. Parse the cleaned string
  const parsed = JSON.parse(cleanJsonString);

  // 3. Return the parsed object as the new item
  return parsed;

} catch (error) {
  // If parsing fails, return a "Failure" state or the raw output for debugging
  return {
    error: "Failed to parse AI output",
    original_output: rawOutput,
    details: error.message,
    ai_hard_failure: true
  };
}

// 1. Data Retrieval
const patch = $('Code in JavaScript2').first().json.patch || {};
const config = $('Code in JavaScript').first().json.order_config;
const currentState = $('If').first().json.selected_intent == 'NEW_ORDER' ? {} : $input.first().json.selections || {};


const intent_map = $('Fetch Intents').first().json.intents;
const user_intent = $('Code in JavaScript2').first().json.selected_intent;

// 2. Setup New Report Structure
let updatedState = { ...currentState, ...patch };
let new_data_items = {};
let new_data_config = {};
let error_items = {};
let missing_items = {};
let intent_data = {};
let active_stage = null;

const patchKeys = Object.keys(patch);

// --- TASK 5: PRE-LOOP STAGE DETECTION (FIXED) ---
// We use Object.keys to ensure we iterate through every field in the order they exist
const allFields = Object.keys(config);

for (const field of allFields) {
  const settings = config[field];
  const value = updatedState[field];

  // A. Check Visibility First
  let isVisible = true;
  if (settings.visibility_rule) {
    const dependsOn = settings.visibility_rule.depends_on;
    const showIf = settings.visibility_rule.show_if;
    if (updatedState[dependsOn] !== showIf) {
      isVisible = false;
    }
  }

  // B. If it's visible, check if it's truly empty
  if (isVisible) {
    const isEmpty = value === undefined || value === null || String(value).trim() === "";

    if (isEmpty) {
      active_stage = settings.step_group;
      break; // Exit loop at the first missing required visible field
    }
  }
}

// 3. Universal Validation Loop
for (const field in config) {
  const settings = config[field];
  const value = updatedState[field];

  // A. Dynamic Visibility & Auto-Cleanup
  if (settings.visibility_rule) {
    const dependsOn = settings.visibility_rule.depends_on;
    const showIf = settings.visibility_rule.show_if;
    if (updatedState[dependsOn] !== showIf) {
      delete updatedState[field]; 
      continue; 
    }
  }

  let fieldError = null;

  // B. Required Check & Stage Filtering
  const isEmpty = value === undefined || value === null || String(value).trim() === "";

  if (isEmpty) {
    // Only show missing items that belong to the current active_stage
    if (settings.step_group === active_stage) {
      if (Object.keys(missing_items).length < 2) {
        missing_items[field] = config[field];
      }
    }
    continue;
  }

  // C. Options Check
  if (settings.options && Array.isArray(settings.options) && settings.options.length > 0) {
    const isAllowed = settings.options.some(opt =>
      opt.toString().toLowerCase() === value.toString().toLowerCase()
    );
    if (!isAllowed) {
      fieldError = `"${value}" isn't an option for ${field}. We offer: ${settings.options.join(", ")}.`;
    }
  }

  // D. Lead Time Constraint Check (Option A - Dedicated Column)
  const constraints = settings.constraints || {};
  if (!fieldError && constraints.min_days_notice) {
    const selectedDate = new Date(value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const minLeadDate = new Date(today);
    minLeadDate.setDate(today.getDate() + constraints.min_days_notice);

    if (selectedDate < minLeadDate) {
      fieldError = `I'm sorry, we need at least ${constraints.min_days_notice} days notice. The earliest available date is ${minLeadDate.toDateString()}.`;
    }
  }

  // E. Cross-Field Logic
  const logic = settings.validation_logic;
  if (!fieldError && logic && logic.controlled_by) {
    const controllerValue = updatedState[logic.controlled_by];
    if (controllerValue && logic.allowed_map) {
      const allowed = logic.allowed_map[controllerValue];
      const allowedList = typeof allowed === 'string' ? JSON.parse(allowed) : (allowed || []);
      if (Array.isArray(allowedList) && allowedList.length > 0 && !allowedList.includes(value.toString())) {
        fieldError = `${field} "${value}" is unavailable for ${logic.controlled_by} "${controllerValue}". Options: ${allowedList.join(", ")}.`;
      }
    }
  }

  // F. Categorize results
  if (fieldError) {
    error_items[field] = fieldError;
  } else if (patchKeys.includes(field)) {
    new_data_items[field] = value;
    new_data_config[field] = config[field];
  }
}

intent_data[user_intent] = intent_map[user_intent];

const has_errors = Object.keys(error_items).length > 0;
const has_missing_data = Object.keys(missing_items).length > 0;
const is_complete = !has_errors && !has_missing_data;

return {
    has_new_data: Object.keys(new_data_items).length > 0,
    new_data: new_data_items,
    new_data_config: new_data_config,
    has_errors: has_errors,
    has_missing_data: has_missing_data,
    is_complete: is_complete,
    errors: error_items,
    missing: missing_items,
    user_intent: user_intent,
    intent_data: intent_data,
    updated_state: updatedState
};

